  ('af8eadb5-d2a7-5f33-870a-86906254644a'::uuid, 'bad57e83-d3b7-5709-bd48-7d5cf5c9bde2'::uuid, 'Shoreham Bank', 'Shoreham Bank · SBA 7(a) lender', array['SBA_7A']::text[], array['COMMERCIAL']::text[], 5000000::bigint, 500000000::bigint, null::numeric, null::numeric, array['first']::text[], null::text, null::numeric, null::numeric, 'Directory BK-035: tier A, high confidence, lends in CA: Yes. States not set (empty means nationwide): confirm the footprint before approving. | Footprint: National (says it lends in all 50 states) | Programs (as published): SBA 7(a) standard, Small SBA loans, USDA B&I, Commercial loans | Term: 10-25 years depending on tier | Broker program: Its broker page publishes a ''3-2-1'' referral program. It pays 3% (Tier 3: $350K-$5M, 25-year term), 2% (Tier 2: 15-25-year term) or 1% (Tier 1: from $50K, 10-25-year term) on SBA 7(a) or USDA B&I loans. A Preferred Broker Program adds +0.5 pt at $2.5M referred or +1 pt at $5M with at least 2 deals. The 2026 promotion required commitment by 10/31/2026 and funding by 12/31/2026,… | Broker page: https://shoreham.bank/brokers-overview | Phone: (401) 773-9509 | Second check: Verified (active 2026: Yes). shoreham.bank/brokers-overview is a live broker page with (401) 773-9509 and a 2026 Preferred Broker Program; the bank says it lends in all 50 states with SBA 7(a) up to $5M, but no CA-speci… | Fit: A national SBA PLP with one of the highest published broker payouts (well above the 1% industry norm in Coleman''s survey). A strong 7(a) outlet for California owner-user real estate. The fee must be disclosed on SBA Form 159. | Source: https://shoreham.bank/brokers-overview'),
  ('d987d9cd-6ce9-53a1-bcc9-d65b52b342f8'::uuid, '14564fdd-4cb2-5589-9a7c-ce0c3cae711d'::uuid, 'Community Reinvestment Fund, USA', 'Community Reinvestment Fund, USA (CRF) · SBA 7(a) lender', array['SBA_7A']::text[], array['COMMERCIAL']::text[], 10000000::bigint, 500000000::bigint, null::numeric, null::numeric, array['first']::text[], null::text, null::numeric, null::numeric, 'Directory BK-037: tier B, medium confidence, lends in CA: Unconfirmed. States not set (empty means nationwide): confirm the footprint before approving. | Footprint: National (SBA 7(a) loans closed across the country) | Programs (as published): SBA 7(a) (Preferred Lender, non-bank), fixed-rate option, real estate among eligible uses | Broker program: Its referral program page says partners sign a partnership agreement and CRF pays a ''competitive'' referral fee once an SBA 7(a) loan closes and funds. The fee amount is not published. | Broker page: https://smallbusiness.crfusa.com/referral-program/ | Fit: A national non-bank 7(a) PLP with a documented, paid referral-partner program. California lending was not specifically confirmed, so check before sending CA owner-user deals. The fee must be disclosed on SBA Form 159. | Source: https://smallbusiness.crfusa.com/referral-program/'),
  ('d101abcc-2492-5090-a209-145acef8cdd3'::uuid, '5f6c4252-48c9-59c6-96b6-e1a106ab304e'::uuid, 'Lendistry', 'Lendistry · SBA 7(a) lender', array['SBA_7A']::text[], array['COMMERCIAL']::text[], null::bigint, 500000000::bigint, null::numeric, null::numeric, array['first']::text[], null::text, null::numeric, null::numeric, 'Directory BK-038: tier B, medium confidence, lends in CA: Yes. States not set (empty means nationwide): confirm the footprint before approving. | Footprint: National, California-based (CDFI) | Programs (as published): SBA 7(a) (non-bank SBLC, Preferred Lender), Conventional CRE term loan, Small business loans | Term: SBA 7(a) up to 25 years for real estate; conventional CRE up to 10 years with 25-year amortization | Broker program: No broker program found. | Fit: An LA-based minority-led CDFI and one of the few non-bank SBLCs licensed for SBA 7(a). Useful for underserved and mission-driven owner-user borrowers. Broker compensation policy is unknown. | Source: https://lendistry.com/small-business-lending'),
  ('a2923ce6-a74b-587f-a643-df6d25d63c7f'::uuid, 'af17ed97-4602-57c9-b33b-30f39f876d27'::uuid, 'Redwood Credit Union', 'Redwood Credit Union (RCU) · SBA 7(a) lender', array['SBA_7A', 'SBA_504']::text[], array['COMMERCIAL']::text[], 5000000::bigint, 500000000::bigint, 60.0::numeric, null::numeric, array['first']::text[], null::text, null::numeric, null::numeric, 'Directory BK-040: tier B, medium confidence, lends in CA: Yes. States not set (empty means nationwide): confirm the footprint before approving. | Footprint: North Bay / Northern California; commercial loans on California properties only | Programs (as published): SBA 7(a) (Preferred Lender), SBA 504 (with CDC partners), Conventional CRE loans | Leverage: Older article cites a conservative 60% LTV on CRE (may be outdated) | Term: SBA 7(a) 7-25 years; CRE amortization up to 30 years (third-party) | Broker program: No broker program found. Applications go through branches or the Business Services office. | Fit: A top Bay Area SBA lender since 2008 and an SBA PLP, with CRE loans reportedly up to $10M (third-party). Lends on California property only. A good North Bay owner-user outlet. Lender type is set to ''Bank'' (no credit-union value). | Source: https://www.redwoodcu.org/?p=2659')
) as v (id, panel_id, panel_name, label, programs, asset_classes, min_loan_cents, max_loan_cents, max_ltv_pct, max_ltc_pct, lien_positions, recourse, rate_min_pct, rate_max_pct, notes)
left join public.lender_panel own on own.id = v.panel_id
left join lateral (select p.id from public.lender_panel p where lower(p.name) = lower(v.panel_name) order by p.created_at limit 1) named on true
where coalesce(own.id, named.id) is not null
on conflict (id) do nothing;
